"use client";

import { type ClipboardEvent, type KeyboardEvent, useRef, useState } from "react";
import { cx } from "../utils/cx";
import { Tag } from "./tag";

export type TagInputProps = {
  "aria-label"?: string;
  id?: string;
  value?: string[];
  defaultValue?: string[];
  onValueChange?: (value: string[]) => void;
  placeholder?: string;
  /** Reject a tag (return false). Duplicates are always ignored. */
  validate?: (tag: string) => boolean;
  /** Keys that commit the text as a tag besides Enter. Default `[","]`. */
  separators?: string[];
  max?: number;
  disabled?: boolean;
  className?: string;
};

/** Free-form tags: type and press Enter or a comma, paste a list, Backspace removes the last. */
export function TagInput({
  value: controlled,
  defaultValue = [],
  onValueChange,
  placeholder,
  validate,
  separators = [","],
  max,
  disabled,
  className,
  id,
  ...rest
}: TagInputProps) {
  const [inner, setInner] = useState(defaultValue);
  const tags = controlled ?? inner;
  const [text, setText] = useState("");
  const field = useRef<HTMLInputElement>(null);
  const commit = (next: string[]) => {
    if (controlled === undefined) setInner(next);
    onValueChange?.(next);
  };
  const add = (raw: string) => {
    const parts = raw
      .split(new RegExp(`[${separators.map((s) => s.replace(/[\]\\^-]/g, "\\$&")).join("")}\\n]`))
      .map((t) => t.trim())
      .filter(Boolean);
    let next = tags;
    for (const t of parts) {
      if (max !== undefined && next.length >= max) break;
      if (next.includes(t) || (validate && !validate(t))) continue;
      next = [...next, t];
    }
    if (next !== tags) commit(next);
    setText("");
  };
  const key = (e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Enter" || separators.includes(e.key)) {
      if (text.trim()) {
        e.preventDefault();
        add(text);
      } else if (e.key === "Enter") e.preventDefault();
    } else if (e.key === "Backspace" && !text && tags.length) commit(tags.slice(0, -1));
  };
  const paste = (e: ClipboardEvent<HTMLInputElement>) => {
    const t = e.clipboardData.getData("text");
    if (/[,\n]/.test(t)) {
      e.preventDefault();
      add(t);
    }
  };
  return (
    // biome-ignore lint/a11y/useKeyWithClickEvents: the input inside takes the keyboard; the click focuses it
    <div
      className={cx("hm-tag-input hm-control", className)}
      data-disabled={disabled ? "" : undefined}
      onClick={() => field.current?.focus()}
    >
      {tags.map((t) => (
        <Tag
          key={t}
          onRemove={(e) => {
            e.stopPropagation();
            commit(tags.filter((x) => x !== t));
            field.current?.focus();
          }}
        >
          {t}
        </Tag>
      ))}
      <input
        {...rest}
        ref={field}
        id={id}
        type="text"
        className="hm-tag-input-field"
        value={text}
        disabled={disabled || (max !== undefined && tags.length >= max)}
        placeholder={tags.length ? undefined : placeholder}
        autoComplete="off"
        onChange={(e) => setText(e.target.value)}
        onKeyDown={key}
        onPaste={paste}
        onBlur={() => text.trim() && add(text)}
      />
    </div>
  );
}
